diff --git a/app/Http/Controllers/CheckoutController.php b/app/Http/Controllers/CheckoutController.php
index 4371a07..a46d9ed 100755
--- a/app/Http/Controllers/CheckoutController.php
+++ b/app/Http/Controllers/CheckoutController.php
@@ -6,6 +6,7 @@ use App\Models\Charge;
 use App\Models\Order;
 use Illuminate\Http\JsonResponse;
 use Illuminate\Http\Request;
+use Illuminate\Database\QueryException;
 use Illuminate\Support\Facades\Http;

 class CheckoutController extends Controller
@@ -18,12 +19,35 @@ class CheckoutController extends Controller

         $order = Order::findOrFail($data['order_id']);

-        $response = Http::asJson()
+        $idempotencyKey = $request->header('Idempotency-Key');
+        if (is_string($idempotencyKey) && $idempotencyKey !== '') {
+            $charge = Charge::where('idempotency_key', $idempotencyKey)->first();
+
+            if ($charge !== null) {
+                if ($charge->order_id !== $order->id) {
+                    abort(409, 'idempotency key was already used for another order');
+                }
+
+                // Recover the local completion if the original request died after
+                // recording the charge but before marking the order paid.
+                $order->markPaid();
+
+                return $this->successResponse($charge, $order);
+            }
+        } else {
+            $idempotencyKey = null;
+        }
+
+        $providerRequest = Http::asJson()
             ->withToken((string) config('services.paylane.key', 'test'))
-            ->post('https://api.paylane.example/v1/charges', [
-                'order_id' => $order->id,
-                'amount_cents' => $order->total_cents,
-            ]);
+            ->when($idempotencyKey !== null, fn ($request) => $request->withHeaders([
+                'Idempotency-Key' => $idempotencyKey,
+            ]));
+
+        $response = $providerRequest->post('https://api.paylane.example/v1/charges', [
+            'order_id' => $order->id,
+            'amount_cents' => $order->total_cents,
+        ]);

         $response->throw();

@@ -33,18 +57,37 @@ class CheckoutController extends Controller
             abort(502, 'provider did not return a payment reference');
         }

-        Charge::create([
+        $chargeData = [
             'order_id' => $order->id,
             'customer_id' => $order->customer_id,
             'reference' => $reference,
             'amount_cents' => $order->total_cents,
-        ]);
+            'idempotency_key' => $idempotencyKey,
+        ];
+
+        try {
+            $charge = Charge::create($chargeData);
+        } catch (QueryException $exception) {
+            if ($idempotencyKey === null) {
+                throw $exception;
+            }
+
+            $charge = Charge::where('idempotency_key', $idempotencyKey)->first();
+            if ($charge === null || $charge->order_id !== $order->id) {
+                throw $exception;
+            }
+        }

         $order->markPaid();

+        return $this->successResponse($charge, $order);
+    }
+
+    private function successResponse(Charge $charge, Order $order): JsonResponse
+    {
         return response()->json([
             'order' => ['id' => $order->id, 'status' => $order->status],
-            'reference' => $reference,
+            'reference' => $charge->reference,
         ]);
     }
 }
